var mapall = new google.maps.Map(document.getElementById('mapall'), {
  zoom: 9.999,
  // disable the default User Interface
  disableDefaultUI: true,
  // add back fullscreen, streetview, zoom
  zoomControl: true,
  streetViewControl: true,
  fullscreenControl: true,
  //panamaram center
  center: new google.maps.LatLng(11.542841751488135, 76.02595022698385),
  //	mapTypeId: google.maps.MapTypeId.ROADMAP,
  mapId: 'f03033acde18bc0d'
});
var infowindow = new google.maps.InfoWindow();
var  i;
var markers = [];



for (i = 0; i < bwlocations.length; i++) {

 new google.maps.DirectionsService().route({
      origin: new google.maps.LatLng( 11.605943, 76.083429), // origin is bw stay
      destination: new google.maps.LatLng(bwlocations[i][1], bwlocations[i][2]),
      travelMode: google.maps.TravelMode.DRIVING,
    }, (response, status) => {
        if (status === "OK") {
          new google.maps.DirectionsRenderer({
						  map: mapall,
						  suppressMarkers: true,
						  polylineOptions: {
							strokeColor: '#4285F4',
							strokeWeight: 4,
							strokeOpacity: 0.8
						  }
						}).setDirections(response);
        }
  })

  marker = new google.maps.Marker({
    position: new google.maps.LatLng(bwlocations[i][1], bwlocations[i][2]),
    icon: bwlocations[i][4],
    map: mapall
  });


  google.maps.event.addListener(marker, 'click', (function (marker, i) {
    return function () {
      infowindow.setContent(bwlocations[i][0]);
      infowindow.open(mapall, marker);
    }
  })(marker, i));

}





